SELECT CASE WHEN units >= 38 THEN 'PREMIUM' ELSE 'STANDARD' END AS units_tier, DATE_TRUNC('YEAR', sale_date) AS year_start, CASE WHEN revenue >= 4300 THEN 'HIGH' ELSE 'LOW' END AS revenue_tier, COUNT(*) AS num_rows, COUNT(*) AS num_rows_2, CORR(units, revenue) AS corr_units_revenue, DENSE_RANK() OVER (PARTITION BY CASE WHEN units >= 38 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY COUNT(*) DESC) AS num_rows_dense_rank FROM store_sales GROUP BY CASE WHEN units >= 38 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('YEAR', sale_date), CASE WHEN revenue >= 4300 THEN 'HIGH' ELSE 'LOW' END HAVING corr_units_revenue >= 0;
